const CloudkuMurotalAPI = require('./main.cjs');

class TestRunner {
    constructor() {
        this.api = new CloudkuMurotalAPI();
        this.passed = 0;
        this.failed = 0;
        this.total = 0;
        this.testResults = [];
    }

    async test(name, testFn) {
        this.total++;
        process.stdout.write(`Testing ${name}... `);
        
        try {
            const result = await testFn();
            console.log('PASS');
            this.passed++;
            this.testResults.push({ name, status: 'PASS', result });
        } catch (error) {
            console.log('FAIL');
            console.log(`   Error: ${error.message}`);
            this.failed++;
            this.testResults.push({ name, status: 'FAIL', error: error.message });
        }
    }

    async runBasicTests() {
        console.log('Basic Module Tests\n');

        await this.test('Require Check', async () => {
            if (typeof CloudkuMurotalAPI !== 'function') {
                throw new Error('Require failed');
            }
            return 'Require successful';
        });

        await this.test('Instance Creation', async () => {
            const api = new CloudkuMurotalAPI();
            if (!api.baseURL) {
                throw new Error('Instance creation failed');
            }
            return `Base URL: ${api.baseURL}`;
        });

        await this.test('Custom Base URL', async () => {
            const customApi = new CloudkuMurotalAPI('https://example.com');
            if (customApi.baseURL !== 'https://example.com') {
                throw new Error('Custom base URL not set correctly');
            }
            return 'Custom base URL working correctly';
        });

        await this.test('User Agent Check', async () => {
            if (!this.api.userAgent || this.api.userAgent !== 'cloudku-murotal/2.0.0') {
                throw new Error('User agent not set correctly');
            }
            return `User Agent: ${this.api.userAgent}`;
        });
    }

    async runCityTests() {
        console.log('\nCity and Location Tests\n');

        await this.test('Get All Cities', async () => {
            const result = await this.api.getAllCities();
            if (!result.status || result.status !== 'success') {
                throw new Error('Invalid response status');
            }
            if (!result.result) {
                throw new Error('No cities data');
            }
            return `Cities retrieved: ${Array.isArray(result.result) ? result.result.length : 'unknown'} items`;
        });

        await this.test('Search Cities with Query', async () => {
            const result = await this.api.searchCities('jakarta');
            if (!result.status || result.status !== 'success') {
                throw new Error('Invalid response status');
            }
            return 'City search successful';
        });

        await this.test('Search Cities without Query (should fail)', async () => {
            try {
                await this.api.searchCities();
                throw new Error('Should have thrown an error for missing query');
            } catch (error) {
                if (error.message.includes('Search query is required')) {
                    return 'Validation working correctly';
                }
                throw error;
            }
        });
    }

    async runPrayerTimeTests() {
        console.log('\nPrayer Times Tests\n');

        await this.test('Prayer Times with Parameters', async () => {
            try {
                const result = await this.api.getPrayerTimesByDate('1', '2024-01-01');
                if (result && typeof result === 'object') {
                    return 'Prayer times request successful';
                }
            } catch (error) {
                if (error.message.includes('HTTP')) {
                    return 'Prayer times endpoint responsive (may need valid city ID)';
                }
                throw error;
            }
        });

        await this.test('Prayer Times by Month', async () => {
            try {
                const result = await this.api.getPrayerTimesByMonth('1', '1', '2024');
                if (result && typeof result === 'object') {
                    return 'Monthly prayer times request successful';
                }
            } catch (error) {
                if (error.message.includes('HTTP')) {
                    return 'Monthly prayer times endpoint responsive';
                }
                throw error;
            }
        });

        await this.test('Prayer Times without City ID (should fail)', async () => {
            try {
                await this.api.getPrayerTimesByDate();
                throw new Error('Should have thrown an error for missing city ID');
            } catch (error) {
                if (error.message.includes('City ID is required')) {
                    return 'Validation working correctly';
                }
                throw error;
            }
        });
    }

    async runHijriDateTests() {
        console.log('\nHijri Date Tests\n');

        await this.test('Current Hijri Date', async () => {
            const result = await this.api.getCurrentHijriDate();
            if (!result.status || result.status !== 'success') {
                throw new Error('Invalid response status');
            }
            if (!result.result) {
                throw new Error('No hijri date data');
            }
            return 'Current Hijri date retrieved successfully';
        });

        await this.test('Hijri Date by Gregorian', async () => {
            const result = await this.api.getHijriDateByGregorian('2024-01-01');
            if (!result.status || result.status !== 'success') {
                throw new Error('Invalid response status');
            }
            return 'Hijri date conversion successful';
        });

        await this.test('Hijri Date without Date (should fail)', async () => {
            try {
                await this.api.getHijriDateByGregorian();
                throw new Error('Should have thrown an error for missing date');
            } catch (error) {
                if (error.message.includes('Gregorian date is required')) {
                    return 'Validation working correctly';
                }
                throw error;
            }
        });
    }

    async runAsmaulHusnaTests() {
        console.log('\nAsmaul Husna Tests\n');

        await this.test('All Asmaul Husna', async () => {
            const result = await this.api.getAllAsmaulHusna();
            if (!result.status || result.status !== 'success') {
                throw new Error('Invalid response status');
            }
            if (!Array.isArray(result.result)) {
                throw new Error('Result should be array');
            }
            return `Asmaul Husna list: ${result.result.length} items`;
        });

        await this.test('Random Asmaul Husna', async () => {
            const result = await this.api.getRandomAsmaulHusna();
            if (!result.status || result.status !== 'success') {
                throw new Error('Invalid response status');
            }
            if (!result.result) {
                throw new Error('No Asmaul Husna data');
            }
            return 'Random Asmaul Husna retrieved successfully';
        });

        await this.test('Asmaul Husna by Number', async () => {
            const result = await this.api.getAsmaulHusnaByNumber(1);
            if (!result.status || result.status !== 'success') {
                throw new Error('Invalid response status');
            }
            if (!result.result) {
                throw new Error('No Asmaul Husna data');
            }
            return 'Asmaul Husna by number retrieved successfully';
        });

        await this.test('Asmaul Husna without Number (should fail)', async () => {
            try {
                await this.api.getAsmaulHusnaByNumber();
                throw new Error('Should have thrown an error for missing number');
            } catch (error) {
                if (error.message.includes('Asmaul Husna number is required')) {
                    return 'Validation working correctly';
                }
                throw error;
            }
        });
    }

    async runQuranTests() {
        console.log('\nQuran Tests\n');

        await this.test('Surah List', async () => {
            const result = await this.api.getSurahList();
            if (!result.status || result.status !== 'success') {
                throw new Error('Invalid response status');
            }
            if (!Array.isArray(result.result)) {
                throw new Error('Result should be array');
            }
            return `Surah list: ${result.result.length} items`;
        });

        await this.test('Random Surah', async () => {
            const result = await this.api.getRandomSurah();
            if (!result.status || result.status !== 'success') {
                throw new Error('Invalid response status');
            }
            if (!result.result) {
                throw new Error('No surah data');
            }
            return 'Random surah retrieved successfully';
        });

        await this.test('Surah by Number', async () => {
            const result = await this.api.getSurahByNumber(1);
            if (!result.status || result.status !== 'success') {
                throw new Error('Invalid response status');
            }
            if (!result.result) {
                throw new Error('No surah data');
            }
            return 'Surah by number retrieved successfully';
        });

        await this.test('Single Ayah', async () => {
            const result = await this.api.getSingleAyah(1, 1);
            if (!result.status || result.status !== 'success') {
                throw new Error('Invalid response status');
            }
            if (!result.result) {
                throw new Error('No ayah data');
            }
            return 'Single ayah retrieved successfully';
        });

        await this.test('Random Ayah', async () => {
            const result = await this.api.getRandomAyah();
            if (!result.status || result.status !== 'success') {
                throw new Error('Invalid response status');
            }
            if (!result.result) {
                throw new Error('No ayah data');
            }
            return 'Random ayah retrieved successfully';
        });

        await this.test('Ayah by Number', async () => {
            const result = await this.api.getAyahByNumber(1);
            if (!result.status || result.status !== 'success') {
                throw new Error('Invalid response status');
            }
            if (!result.result) {
                throw new Error('No ayah data');
            }
            return 'Ayah by number retrieved successfully';
        });

        await this.test('Juz by Number', async () => {
            const result = await this.api.getJuzByNumber(1);
            if (!result.status || result.status !== 'success') {
                throw new Error('Invalid response status');
            }
            if (!result.result) {
                throw new Error('No juz data');
            }
            return 'Juz retrieved successfully';
        });

        await this.test('Ayah Range', async () => {
            try {
                const result = await this.api.getAyahRange(1, 1, 5);
                if (result && typeof result === 'object') {
                    return 'Ayah range request successful';
                }
            } catch (error) {
                if (error.message.includes('HTTP')) {
                    return 'Ayah range endpoint responsive';
                }
                throw error;
            }
        });
    }

    async runThemeTests() {
        console.log('\nTheme Tests\n');

        await this.test('All Themes', async () => {
            const result = await this.api.getAllThemes();
            if (!result.status || result.status !== 'success') {
                throw new Error('Invalid response status');
            }
            if (!Array.isArray(result.result)) {
                throw new Error('Result should be array');
            }
            return `Themes list: ${result.result.length} items`;
        });

        await this.test('Ayah by Theme', async () => {
            try {
                const result = await this.api.getAyahByTheme(1);
                if (result && typeof result === 'object') {
                    return 'Ayah by theme request successful';
                }
            } catch (error) {
                if (error.message.includes('HTTP')) {
                    return 'Ayah by theme endpoint responsive';
                }
                throw error;
            }
        });
    }

    async runDoaTests() {
        console.log('\nDua Tests\n');

        await this.test('Dua Sources', async () => {
            const result = await this.api.getDoaSources();
            if (!result.status || result.status !== 'success') {
                throw new Error('Invalid response status');
            }
            if (!result.result) {
                throw new Error('No dua sources data');
            }
            return 'Dua sources retrieved successfully';
        });

        await this.test('Random Dua', async () => {
            const result = await this.api.getRandomDua();
            if (!result.status || result.status !== 'success') {
                throw new Error('Invalid response status');
            }
            if (!result.result) {
                throw new Error('No dua data');
            }
            return 'Random dua retrieved successfully';
        });

        await this.test('Search Dua', async () => {
            const result = await this.api.searchDua('harian');
            if (!result.status || result.status !== 'success') {
                throw new Error('Invalid response status');
            }
            return 'Dua search successful';
        });

        await this.test('Search Dua without Query (should fail)', async () => {
            try {
                await this.api.searchDua();
                throw new Error('Should have thrown an error for missing query');
            } catch (error) {
                if (error.message.includes('Search query is required')) {
                    return 'Validation working correctly';
                }
                throw error;
            }
        });
    }

    async runHadithTests() {
        console.log('\nHadith Tests\n');

        await this.test('Random Hadith Arbain', async () => {
            const result = await this.api.getRandomHadithArbain();
            if (!result.status || result.status !== 'success') {
                throw new Error('Invalid response status');
            }
            if (!result.result) {
                throw new Error('No hadith data');
            }
            return 'Random Hadith Arbain retrieved successfully';
        });

        await this.test('Random Hadith Bukhari', async () => {
            const result = await this.api.getRandomHadithBukhari();
            if (!result.status || result.status !== 'success') {
                throw new Error('Invalid response status');
            }
            if (!result.result) {
                throw new Error('No hadith data');
            }
            return 'Random Hadith Bukhari retrieved successfully';
        });
    }

    async runDateFormatTests() {
        console.log('\nDate Formatting Tests\n');

        await this.test('Date Format Function', async () => {
            const formatted = this.api.formatDate('2008-12-28');
            if (formatted !== '28-12-2008') {
                throw new Error(`Expected '28-12-2008', got '${formatted}'`);
            }
            return 'Date formatting working correctly';
        });

        await this.test('Invalid Date Format', async () => {
            const result = this.api.formatDate('invalid-date');
            if (result !== 'invalid-date') {
                throw new Error('Should return original string for invalid dates');
            }
            return 'Invalid date handling working correctly';
        });

        await this.test('Null Date Format', async () => {
            const result = this.api.formatDate(null);
            if (result !== null) {
                throw new Error('Should return null for null input');
            }
            return 'Null date handling working correctly';
        });
    }

    async runErrorHandlingTests() {
        console.log('\nError Handling Tests\n');

        await this.test('Invalid Parameter Type', async () => {
            try {
                await this.api.getAsmaulHusnaByNumber('invalid');
                throw new Error('Should have thrown error for invalid parameter');
            } catch (error) {
                if (error.message.includes('HTTP') || error.message.includes('Request failed')) {
                    return 'Error handling working correctly';
                }
                throw new Error('Unexpected error type');
            }
        });

        await this.test('Network Error Simulation', async () => {
            try {
                const invalidApi = new CloudkuMurotalAPI('https://invalid-domain-test.com');
                await invalidApi.getAllCities();
                throw new Error('Should have thrown network error');
            } catch (error) {
                if (error.message.includes('Request failed') || error.message.includes('fetch')) {
                    return 'Network error handling working correctly';
                }
                throw error;
            }
        });
    }

    async runAll() {
        console.log('CJS Module Complete Test Suite\n');
        console.log('='.repeat(50));

        try {
            await this.runBasicTests();
            await this.runCityTests();
            await this.runPrayerTimeTests();
            await this.runHijriDateTests();
            await this.runAsmaulHusnaTests();
            await this.runQuranTests();
            await this.runThemeTests();
            await this.runDoaTests();
            await this.runHadithTests();
            await this.runDateFormatTests();
            await this.runErrorHandlingTests();
        } catch (error) {
            console.log('Critical error during testing:', error.message);
        }

        this.showResults();
    }

    showResults() {
        console.log('\n' + '='.repeat(50));
        console.log('Test Results:');
        console.log(`Passed: ${this.passed}`);
        console.log(`Failed: ${this.failed}`);
        console.log(`Total: ${this.total}`);
        console.log(`Success Rate: ${((this.passed / this.total) * 100).toFixed(1)}%`);
        
        if (this.failed === 0) {
            console.log('\nAll tests passed! CJS module working correctly.');
        } else {
            console.log('\nSome tests failed. Check the errors above.');
            
            console.log('\nFailed Tests:');
            this.testResults
                .filter(test => test.status === 'FAIL')
                .forEach(test => {
                    console.log(`- ${test.name}: ${test.error}`);
                });
            
            process.exit(1);
        }

        console.log('\nTest completed.');
    }
}

const runner = new TestRunner();
runner.runAll().catch(error => {
    console.error('Test runner failed:', error);
    process.exit(1);
});